function MyTable(props) {
  const [state, setState] = useState({
    model_type: ['closed_source_model', 'open_source_general_model', 'open_source_special_model'],
    language: 'all',
    showTaskType: false,
    showRoundIndex: false,
    showConcurrencyPerformance: false,
    showProgressionPerformance: false,
    showTaskPlanning: false,
    showErrorProportion: false,
    showRoundType: false,
    showRelevantContextType: false,
    hasDetail: true,
    data: [],
    showSize: 25,
    loading: true,
    year: null, // 字符串格式
    month: null, // 整数格式，0表示1月，1表示2月..., null for year type time
    type: 'month',
    search: null,
    purpose: 'academic',
    appDomain: 'application_software',
    llm: 'Application_Development_Framework',
  });

  // 请求一次数据更新表格。如果还没读取好配置文件则不请求数据。
  useEffect(() => {
    if (props.year == null && props.month == null) {
      console.log('the first loading');
      return;
    }
    updateDate({
      year: String(props.year),
      month: props.month,
    });
  }, [props]);

  const expandData = () => {
    setState({
      ...state,
      showSize: state.showSize + 25,
    });
  };
  const updateDate = (newstate) => {
    console.log('table update', newstate);
    // 先获取原先的表格属性
    let {
      model_type,
      language,
      month,
      year,
      columns,
      showTaskType,
      showRoundIndex,
      showConcurrencyPerformance,
      showProgressionPerformance,
      showTaskPlanning,
      showErrorProportion,
      showRoundType,
      showRelevantContextType,
      hasDetail,
      type,
      search,
      purpose,
      appDomain,
      llm,
    } = state;
    // 然后把表格改为加载中的状态
    setState({ ...state, ...newstate, loading: true });
    // 如果 newstate 有对应的属性，则进行更新
    if (newstate.hasOwnProperty('model_type')) model_type = newstate.model_type;
    if (newstate.hasOwnProperty('language')) language = newstate.language;
    if (newstate.hasOwnProperty('month')) month = newstate.month;
    if (newstate.hasOwnProperty('year')) year = newstate.year;
    if (newstate.hasOwnProperty('showTaskType')) showTaskType = newstate.showTaskType;
    if (newstate.hasOwnProperty('showRoundIndex')) showRoundIndex = newstate.showRoundIndex;
    if (newstate.hasOwnProperty('showConcurrencyPerformance')) showConcurrencyPerformance = newstate.showConcurrencyPerformance;
    if (newstate.hasOwnProperty('showProgressionPerformance')) showProgressionPerformance = newstate.showProgressionPerformance;
    if (newstate.hasOwnProperty('showTaskPlanning')) showTaskPlanning = newstate.showTaskPlanning;
    if (newstate.hasOwnProperty('showErrorProportion')) showErrorProportion = newstate.showErrorProportion;
    if (newstate.hasOwnProperty('showRoundType')) showRoundType = newstate.showRoundType;
    if (newstate.hasOwnProperty('showRelevantContextType')) showRelevantContextType = newstate.showRelevantContextType;
    if (newstate.hasOwnProperty('type')) type = newstate.type;
    if (newstate.hasOwnProperty('search')) search = newstate.search;
    if (newstate.hasOwnProperty('purpose')) purpose = newstate.purpose;
    if (newstate.hasOwnProperty('appDomain')) appDomain = newstate.appDomain;
    if (newstate.hasOwnProperty('llm')) llm = newstate.llm;

    //获取数据大屏的‘t_month’参数

    columns = subsetColumns(showTaskType, showRoundIndex, showConcurrencyPerformance, showProgressionPerformance, showTaskPlanning, showErrorProportion, showRoundType, showRelevantContextType);
    hasDetail = true;

    // fetch 异步请求
    fetch('/records.xlsx')
      .then(response => response.arrayBuffer())
      .then(buffer => {
          const data = new Uint8Array(buffer);
          const workbook = XLSX.read(data, { type: 'array' });
          const firstSheet = workbook.Sheets['指标'];
          const jsonData = XLSX.utils.sheet_to_json(firstSheet).slice(35).filter(item => item.hasOwnProperty('模型类别'));
          const renamedData = jsonData.map(item => {
            const newItem = {};
            Object.keys(item).forEach(oldKey => {
              const newKey = keyMap[oldKey] || oldKey; // 如果没匹配到映射，保留原名
              newItem[newKey] = item[oldKey];
            });
            return newItem;
          });
          const translatedData = renamedData.map(obj => ({
            ...obj,          // 保留其他属性
            model_type: t(obj.model_type)
          }));
          const sortedResult = translatedData.sort((a, b) => b.overall_score - a.overall_score);
          return sortedResult;
      })
      .then((data) => {
        // 根据筛选条件过滤数据
        var filteredData = data
        filteredData = filteredData.filter(item => model_type.includes(item.model_type))
        const translatedData = filteredData.map(obj => ({
          ...obj,          // 保留其他属性
          model_type: t(obj.model_type)
        }));        
        return translatedData;
      })
      .then((data) => {
        // 搜索特定数据
        let queryData;
        if (search) {
          queryData = data.filter((data) => {
            let reg = new RegExp(search.trim(), 'i');
            return reg.test(data.model_name);
          });
          if (queryData.length == 0) {
            message.warning(t('no_result'));
          } else {
            data = queryData;
          }
        }
        // 更新属性和表格数据
        setState({
          ...state,
          ...newstate,
          loading: false,
          columns: columns,
          showTaskType: showTaskType,
          showRoundIndex: showRoundIndex,
          showConcurrencyPerformance: showConcurrencyPerformance,
          showProgressionPerformance: showProgressionPerformance,
          showTaskPlanning: showTaskPlanning,
          showErrorProportion: showErrorProportion,
          showRoundType: showRoundType,
          showRelevantContextType: showRelevantContextType,
          hasDetail: hasDetail,
          data: data,
          purpose: purpose,
          appDomain: appDomain,
          llm: llm,
        });
      })
      .catch((err) => {
        console.log('hi!' + err);
        setState({
          ...state,
          ...newstate,
          loading: false,
          columns: columns,
          data: [],
        });
      });
  };
  const {
    model_type,
    language,
    data,
    columns,
    loading,
    showSize,
    showTaskType,
    showRoundIndex,
    showConcurrencyPerformance,
    showProgressionPerformance,
    showTaskPlanning,
    showErrorProportion,
    showRoundType,
    showRelevantContextType,
    hasDetail,
    month,
    year,
    type,
    purpose,
    appDomain,
    llm,
  } = state;
  return (
    <div className="table">
      <div className="table-content">
        <Card
          style={{
            width: '100%',
            background: '#FFFFFF',
            boxShadow: '0px 15px 20px 15px #F7F7FF',
          }}
        >
          <TablePanel
              model_type={model_type}
            language={language}
            type={type}
            setState={updateDate}
            hasDetail={hasDetail}
            showTaskType={showTaskType}
            showRoundIndex={showRoundIndex}
            showConcurrencyPerformance={showConcurrencyPerformance}
            showProgressionPerformance={showProgressionPerformance}
            showTaskPlanning={showTaskPlanning}
            showErrorProportion={showErrorProportion}
            showRoundType={showRoundType}
            showRelevantContextType={showRelevantContextType}
            month={month}
            year={year}
            purpose={purpose}
            appDomain={appDomain}
            llm={llm}
          />
          <Table
            // Todo
            // scroll={{ x: 1500, y: 300 }}
            columns={columns}
            rowKey={(record) => record.rank}
            dataSource={data.slice(0, Math.min(showSize, data.length))}
            pagination={false}
            loading={loading}
            scroll={{ x: 'max-content' }}
          />
          <Row style={{ marginTop: '10px' }}>
            <Col span={12}>
              <Row justify="start">
                <Col>
                  {showSize < data.length ? (
                    <a
                      style={{
                        color: '#5d83b2',
                        fontSize: '18px',
                      }}
                      onClick={expandData}
                    >
                      {t('showMore') + '>>'}
                    </a>
                  ) : (
                    <span
                      style={{
                        color: 'gray',
                        fontSize: '18px',
                      }}
                    >
                      {t('noMore')}
                    </span>
                  )}
                </Col>
              </Row>
            </Col>
            <Col span={12}>
              <Row justify="end">
                <Col>
                  <QAmiss />
                </Col>
              </Row>
            </Col>
          </Row>
        </Card>
      </div>
    </div>
  );
}

